def _postgis_upgrade() -> None:
    """Optional: spatial column + GiST index when the PostGIS extension is installable.

    lat/lon stay the source of truth; `geog` is a generated column, so nothing
    changes for the app when PostGIS is absent.
    """
    bind = op.get_bind()
    if bind.dialect.name != "postgresql":
        return
    available = bind.execute(sa.text("SELECT 1 FROM pg_available_extensions WHERE name = 'postgis'")).scalar()
    if not available:
        return
    op.execute("CREATE EXTENSION IF NOT EXISTS postgis")
    op.execute(
        "ALTER TABLE places ADD COLUMN geog geography(Point, 4326) GENERATED ALWAYS AS "
        "(ST_SetSRID(ST_MakePoint(lon, lat), 4326)::geography) STORED"
    )
    op.execute("CREATE INDEX ix_places_geog ON places USING GIST (geog)")


